import { useState } from 'react';
import { Copy, Check, Link2, AlertTriangle, CheckCircle2, Eye, Send } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuLabel, DropdownMenuTrigger } from '@/components/ui/dropdown-menu';
import { useToast } from '@/hooks/use-toast';
import { onboardingUrl, onboardingUrlLabel } from '@/config/findableSite';
import { useOnboardingLink, recordOnboardingLinkEvent } from '@/hooks/useOnboardingLink';
import { MANUAL_SEND_CHANNELS, LINK_CHANNEL_LABEL, previewUrl, type OnboardingLinkStatus } from '@/lib/onboardingLinkStatus';
import { refusalText } from '@/lib/salesCrm';
import { isDemoLead } from '@/lib/demoLeads';
import { WorkSection } from '@/components/WorkSection';

/**
 * Exactly the fields this card reads — nothing more. Declared structurally rather than as
 * OutreachLead so the Inbox can pass its own narrow lead row without a cast and without a second
 * copy of this component: the Inbox fetches a slim projection, not the full lead. OutreachLead
 * satisfies this shape, so the lead-detail call site is unchanged.
 */
export interface OnboardingLinkLead {
  id: string;
  business_name?: string | null;
  /* Optional to match OutreachLead, where these are optional. assess() already treats every one of
     them as possibly absent, so widening the type changes no behaviour — it just lets both the full
     lead and the Inbox projection satisfy it without a cast. */
  amount_paid?: number | null;
  category?: string | null;
  search_keyword?: string | null;
  search_location?: string | null;
  address?: string | null;
}

/**
 * COPY THE SIGN-UP LINK for one lead.
 *
 * The link was being typed by hand, and the failure is silent rather than loud: a wrong or missing
 * ?lead= does not error, it just makes a known prospect anonymous. The flow still runs, they can
 * still pay, and only afterwards does it emerge that no baseline exists and the four-week guarantee
 * cannot be measured. So the link is generated, shown, and copied — never retyped.
 */


/**
 * What the sign-up flow needs from a lead, and what degrades without it. Deliberately split into
 * "already paid" (the link is pointless) and "will half-work" (the link functions but something
 * downstream suffers), because those want different words on screen.
 */
/* Exported so the Inbox's compact icon shares this exact judgement. Two copies of "is this lead
   ready for the sign-up link" would drift, and the one that matters most - no trade, so no baseline
   can run - is the one you least want drifting. */
export function assessOnboardingLink(lead: OnboardingLinkLead) {
  /* amount_paid only. Previously a £0 lead in in_delivery was treated as paid and the copy button
     was hidden, withholding the sign-up link from someone who had not actually paid. */
  const paid = (lead.amount_paid ?? 0) > 0;

  const trade = (lead.category ?? lead.search_keyword ?? '').trim();
  const town = (lead.search_location ?? lead.address ?? '').trim();
  const name = (lead.business_name ?? '').trim();

  const warnings: string[] = [];
  // The one that actually breaks something: startPaidBaseline refuses with no_business_type, so a
  // paying client would get no baseline — the exact hole the guarantee is measured through.
  if (!trade) warnings.push('no trade stored, so no baseline can run after they pay');
  // Cosmetic but visible: the form's suggestion chips fall back to generic without a trade, and the
  // headline says "your business" instead of naming them.
  if (!name) warnings.push('no business name, so the page cannot greet them by name');
  // Recoverable by the customer — the town field just starts empty instead of prefilled.
  if (!town) warnings.push('no town on file, so they start with an empty area field');

  return { paid, warnings, blocking: !trade };
}

const shortDay = (iso: string) => new Date(iso).toLocaleString('en-GB', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit', timeZone: 'Europe/London' });

/** Sent? Opened? — one line, from the one rule (src/lib/onboardingLinkStatus.ts). */
export function OnboardingLinkStatusLine({ status }: { status: OnboardingLinkStatus | null | undefined }) {
  if (!status) return null;
  if (status.sentCount === 0) {
    return <p className="text-[11px] text-muted-foreground" data-testid="onboarding-status">Not sent yet{status.generatedAt ? ` · copied ${shortDay(status.generatedAt)}` : ''}. A WhatsApp message carrying this link is recorded automatically.</p>;
  }
  return (
    <p className="text-[11px] leading-relaxed" data-testid="onboarding-status">
      <span className="font-medium text-foreground">Sent</span> <span className="text-muted-foreground">{shortDay(status.firstSentAt!)} ({status.channels.map((c) => LINK_CHANNEL_LABEL[c] ?? c).join(', ')}{status.sentCount > 1 ? `, ${status.sentCount} times` : ''})</span>
      {' · '}
      {status.opened
        ? <><span className="font-medium text-emerald-500">Opened</span> <span className="text-muted-foreground">{shortDay(status.firstOpenedAt!)}{status.openCount > 1 ? ` · ${status.openCount} page loads` : ''}</span></>
        : <span className="font-medium text-amber-500">Not opened yet</span>}
    </p>
  );
}

export function OnboardingLinkCard({ lead }: { lead: OnboardingLinkLead }) {
  const [copied, setCopied] = useState(false);
  const { toast } = useToast();
  const { paid, warnings, blocking } = assessOnboardingLink(lead);
  const url = onboardingUrl(lead.id, lead.business_name);
  const demo = isDemoLead(lead.id);
  const link = useOnboardingLink(demo ? null : lead.id);

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(url);
      setCopied(true);
      setTimeout(() => setCopied(false), 1500);
    } catch {
      /* Clipboard denied (insecure context, or permission refused). The link is on screen and
         selectable, so there is still a way to get it — better than an error toast. */
    }
    // A copy is 'generated', never 'sent' — the WhatsApp message that carries it records the send.
    if (!demo) void recordOnboardingLinkEvent(lead.id, 'generated', null);
  };
  const markSent = async (channel: string, label: string) => {
    const r = await recordOnboardingLinkEvent(lead.id, 'sent', channel);
    if (r.ok) toast({ title: 'Recorded', description: `Sign-up link sent by ${label.toLowerCase()}.` });
    else toast({ title: 'Not recorded', description: refusalText(r.error), variant: 'destructive' });
  };

  const st = link.data?.status;
  const day = (iso: string) => new Date(iso).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', timeZone: 'Europe/London' });
  /* The folded line (declutter pass 2, 2026-10-01): where the link stands, in a few words. */
  const summary = demo ? 'Not sent yet'
    : !st ? '…'
    : st.sentCount === 0 ? (st.generatedAt ? 'Copied, not sent yet' : 'Not sent yet')
    : `Sent ${day(st.firstSentAt!)} · ${st.opened ? 'opened' : 'not opened yet'}`;
  const warningLine = warnings.length > 0 && (
    /* Told BEFORE sending, not after. Amber rather than red when nothing is blocking:
       these links still work, they just cost something downstream. */
    <div className={`flex items-start gap-1.5 text-[11px] leading-relaxed ${blocking ? 'text-orange-400' : 'text-amber-400/90'}`} data-testid="onboarding-warning">
      <AlertTriangle className="mt-0.5 h-3.5 w-3.5 shrink-0" />
      <span>
        {warnings.length === 1 ? 'Heads up: ' : 'Heads up — '}
        {warnings.join('; ')}.
      </span>
    </div>
  );

  /* Already paid: one line, nothing to open. Sending an existing client back to checkout wastes their
     time and ours — findable-checkout would refuse it anyway with already_client. */
  if (paid) {
    return <WorkSection icon={CheckCircle2} iconClass="text-emerald-500" title="Sign-up link" testId="signup-link" summary="Not needed — they have signed up and paid" />;
  }
  return (
    /* ⛔ A BLOCKING GAP (no trade → no baseline after they pay) stays visible while folded; the softer
       heads-ups are inside, next to the link they are about. */
    <WorkSection icon={Link2} iconClass="text-sky-400" title="Sign-up link" testId="signup-link" summary={summary}
      summaryClass={st && st.sentCount > 0 && st.opened ? 'text-emerald-600 dark:text-emerald-400' : undefined}
      alert={blocking ? warningLine : null}>
          {/* The link, visible before it goes anywhere. Shown scheme-less because the https:// is
              noise, and break-all so a long uuid wraps rather than stretching the dialog. */}
          <p className="mb-2 break-all rounded-md bg-muted/40 px-2 py-1.5 font-mono text-[10.5px] leading-relaxed text-muted-foreground">
            {onboardingUrlLabel(lead.id, lead.business_name)}
          </p>

          {/* ⛔ WRAPS (2026-10-01): at 390 px the three buttons ran past the card. Copy takes the first line on a
              phone, Preview and Sent another way share the next; taller touch targets below sm. */}
          <div className="flex flex-wrap gap-1.5" data-testid="onboarding-buttons">
            <Button
              size="sm"
              variant="outline"
              className="h-9 min-w-[11rem] flex-[2_1_11rem] gap-1.5 text-xs sm:h-8"
              onClick={copy}
            >
              {copied ? <Check className="h-3.5 w-3.5 text-green-500" /> : <Copy className="h-3.5 w-3.5" />}
              {copied ? 'Copied' : 'Copy sign-up link'}
            </Button>
            {/* ⛔ PREVIEW = preview=1, so our own look is recorded as a preview and never as their open. */}
            <Button asChild size="sm" variant="outline" className="h-9 flex-1 gap-1 px-2.5 text-xs sm:h-8 sm:flex-none" title="Open it yourself. Your visit is not counted as their open.">
              <a href={previewUrl(url)} target="_blank" rel="noopener noreferrer"><Eye className="h-3.5 w-3.5" />Preview</a>
            </Button>
            {!demo && (
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button size="sm" variant="outline" className="h-9 flex-1 gap-1 whitespace-nowrap px-2.5 text-xs sm:h-8 sm:flex-none" title="Sent it by email, LinkedIn or in person? Record it here. WhatsApp is recorded automatically."><Send className="h-3.5 w-3.5" />Sent another way</Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="end">
                  <DropdownMenuLabel className="text-xs">I sent the link by…</DropdownMenuLabel>
                  {MANUAL_SEND_CHANNELS.map((c) => <DropdownMenuItem key={c.value} className="text-xs" onClick={() => void markSent(c.value, c.label)}>{c.label}</DropdownMenuItem>)}
                </DropdownMenuContent>
              </DropdownMenu>
            )}
          </div>
          <div className="mt-2"><OnboardingLinkStatusLine status={link.data?.status} /></div>
          {!blocking && warningLine && <div className="mt-2">{warningLine}</div>}
    </WorkSection>
  );
}
