export function isRealCompetitor(name: string, locationText: string): boolean {
  if (isFurnitureOrFranken(name)) return false;          // page furniture / fused link labels
  // Strip trailing fragments the extractor leaves on: punctuation, then a dangling article/
  // conjunction ("QuickBooks. The" → "QuickBooks", "Crunch and" → "Crunch"). Also a leading "The ".
  let n = name.trim()
    .replace(/^the\s+/i, '')
    .replace(/[\s.,;:–—-]+$/g, '')                        // trailing punctuation ("QuickBooks." )
    .replace(/\s+(?:the|and|or|a|an|of|for|with|to)$/i, '') // dangling article/conjunction (" The")
    .replace(/[\s.,;:–—-]+$/g, '')                        // punctuation exposed by the strip above
    .trim();
  if (n.length < 3 || n.length > 60) return false;
  if (n.includes('@')) return false;                     // social handle, not a venue ("… (@kava_thailand)")
  const nl = n.toLowerCase();
  if (PLACEHOLDER_VALUES.has(nl)) return false;          // table header / placeholder / prose fragment
  if (UI_PHRASES.some((p) => nl === p || nl.includes(p))) return false;          // "gemini apps activity" etc.
  const words = nl.split(/\s+/).map((w) => w.replace(/[^a-z0-9.&'-]/g, '')).filter(Boolean);
  if (!words.length) return false;
  // Gov/tax authority, statutory term, or accounting software → never a competing firm.
  if (isNotACompetitor(nl, words)) return false;
  /* Provably-not-a-firm strings from the raw regex extractor: a single English function word
     ("always", "ask") — the same marker test the market fold uses, so a report and the panel can
     never disagree — PLUS a code-like token.
     ⛔ THE CODE-LIKE HALF WAS ADDED 2026-08-28 BECAUSE 48 OF THEM REACHED A HEADLINE. Solene's
     answers carried scraped tracking/video ids ("AAAAABqkCA", "Xdaj6AH7genL7KP9o"), and they pass
     every set above: one token, 4+ chars, capitalised, in no vocabulary list. Structural, so it
     needs no per-trade word list (competitorCleaning.ts) — and swept over all 1,090 names Solene
     really stored: 0 multi-word names and 0 firm-shaped names flagged. */
  if (isProvableJunkName(n)) return false;
  /* A known DIRECTORY (Checkatrade, Yell, Trustpilot…) is a source, not a rival firm a customer
     hires instead — it passed every set above and could print as a client's "competitor". Known
     NATIONALS stay: Able Group really is a rival. (knownEntities.ts, 2026-08-19.) */
  if (classifyKnownEntity(n)?.kind === 'directory') return false;
  const generic = (w: string) =>
    COMPETITOR_STOPWORDS.has(w) || PLATFORM_UI.has(w) || GENERIC_TERMS.has(w) || PRONOUNS.has(w)
    || DOMAIN_GENERIC.has(w) || FRAGMENT_WORDS.has(w) || NOISE_WORDS.has(w);
  // Every word is generic (stopword / descriptor / venue-type / domain word) → not a real
  // name: "Thai Food", "Cocktail Lounge", "Tax Advisors", "Accountancy Services".
  if (words.every(generic)) return false;
  // Ends in a PLURAL category word → a category/list, not a single venue ("Kava Bars").
  if (PLURAL_CATEGORIES.has(words[words.length - 1])) return false;
  const locTokens = locationText.toLowerCase().split(/[^a-z]+/).filter((tk) => tk.length > 2);
  if (locTokens.length && locTokens.every((tk) => nl.includes(tk)) && words.length <= locTokens.length + 1) return false; // basically the location
  if (!/[A-Z0-9]/.test(n)) return false;                 // no capital/digit anywhere → a fragment, not a name
  if (words.length === 1) {
    // Single word: keep a proper-noun-shaped brand token ("Crunch", "Mazuma", "Azets", "IRIS",
    // "TaxAssist"). Drop generics/domain words and very short tokens. (We no longer require a
    // .&digit char — that was wrongly dropping real one-word brand names.)
    const w = words[0];
    if (generic(w) || w.length < 4) return false;
    if (!/^[A-Z]/.test(n)) return false;                 // must start capitalised (a proper noun)
    if (/ing$/.test(w) && w.length >= 5) return false;   // gerund fragment ("Choosing", "Finding") — never a firm
  }
  return true;
}

/** Trim to a sentence boundary near `max` chars (avoid cutting mid-word). */
function trimToSentence(text: string, max: number): string {
  const t = text.trim();
  if (t.length <= max) return t;
  const cut = t.slice(0, max);
  const stop = Math.max(cut.lastIndexOf('. '), cut.lastIndexOf('! '), cut.lastIndexOf('? '));
  return stop > max * 0.5 ? cut.slice(0, stop + 1).trim() : cut.trim() + '…';
}

// A sentence is "damning evidence" if it names the competitor, states the business/
// category doesn't exist, or starts the recommendations — i.e. the point, not the preamble.
function isDamningSentence(s: string, rival?: string): boolean {
  const l = s.toLowerCase();
  if (rival && l.includes(rival.toLowerCase())) return true;
  if (/\b(no|not|none|couldn't|don't|doesn't|aren't|isn't|unable|cannot)\b/.test(l)
    && /\b(any|dedicated|specific|bar|bars|kava|find|aware|exist|listing|results?|options?)\b/.test(l)) return true;
  if (/\b(best|top|recommend(?:ed)?|you might|try|options? include|here are|popular|consider|check out|go to|standout|notable)\b/.test(l)) return true;
  return false;
}

/**
 * Extract 1–3 CLEAN, relevant sentences from an engine answer for the gut-punch — the
 * damning bit (competitor named / doesn't exist / recommendations), not the rambling
 * preamble or UI/markdown junk. Returns null if nothing clean + relevant can be pulled
 * (so pickGutPunch can prefer a different question's answer).
 */
function extractGutPunch(raw: string, rival?: string): string | null {
  const clean = cleanAnswerText(raw);
  if (clean.length < 20) return null;
  const parts = clean.split(/(?<=[.!?])\s+(?=[A-Z0-9"“'])/).map((s) => s.trim()).filter(Boolean);
  const sentences = parts.length ? parts : [clean];
  let start = sentences.findIndex((s) => isDamningSentence(s, rival));
  if (start < 0) return null;                          // no relevant sentence → let another question win
  let out = '';
  for (let i = start; i < sentences.length && i < start + 3; i++) {
    const next = out ? `${out} ${sentences[i]}` : sentences[i];
    if (out && next.length > 340) break;
    out = next;
    if (out.length >= 200) break;
  }
  out = out.trim();
  return out.length >= 20 ? trimToSentence(out, 320) : null;
}

// Head words that signal a broad, unwinnable vanity term ("best bar in X").
const HEAD_TERMS = /\b(best|top|good|great|recommended|popular|leading|favou?rite)\b/i;
// "near me" questions resolve to whatever city the AI guesses (often the WRONG one) — they
// undermine the report's credibility, so they're excluded from gut-punch selection entirely.
const NEAR_ME = /\bnear\s*me\b/i;

// The gut-punch to LEAD the report with: a completed question where an engine did NOT name
// the business and gave clean, damning prose. Ranked by (1) RELEVANCE — a question tied to
// the business's real niche (e.g. "kava", "pool") is a winnable, fixable search and ranks
// far above a broad vanity head term ("best bar in X"), which is deprioritised; then (2)
// whether the answer is damning (doesn't exist / names a real competitor); then (3) clarity.
// "near me" questions are skipped outright. Also returns the top REAL competitor named in the
// chosen answer (for the report's "AI recommended X, Y and others" summary), if any.
/* ⛔ HAS THE MODEL READ THIS RUN? The test is a MAJORITY of answered cells, not "at least one" and
   not "all". Not one: a single model verdict beside eleven string matches cannot carry a headline
   number. Not all: gpt-4o omits an id often enough that the extractor has a retry loop for it
   (CLAUDE.md §8 — "model omitted N of M ids" on ~8% of runs), so demanding every cell would put a
   whole report back behind the hand-check for one missing answer. A majority means the figure on
   the page is mostly the model's reading, and the cells it missed keep their old fallback. */
export function runIsModelRead(rows: QueueRow[]): boolean {
  let read = 0, answered = 0;
  for (const r of rows) {
    if (r.status !== 'done' || !r.result) continue;
    for (const e of SCORED_ENGINES) {
      const c = r.result[e];
      if (!c || !c.answer_text) continue;
      answered++;
      if (hasModelNamedEvidence(c)) read++;
    }
  }
  return answered > 0 && read * 2 > answered;
}

function pickGutPunch(
  rows: QueueRow[],
  locationText: string,
  specialisms: string,
  businessType: string,
): { question: string; engineLabel: string; rivals: string[]; answer: string; businesses: string[] } | null {
  const niche = nicheKeywordsFrom(specialisms, businessType);
  let best: { question: string; engineLabel: string; rivals: string[]; answer: string; businesses: string[] } | null = null;
  let bestScore = -Infinity;
  for (const r of rows) {
    if (r.status !== 'done' || !r.result) continue;
    const q = r.question.toLowerCase();
    if (NEAR_ME.test(q)) continue;                       // never lead with a wrong-city "near me" answer
    const hasNiche = niche.some((k) => q.includes(k));
    const isHead = HEAD_TERMS.test(q);
    /* SCORED_ENGINES only (ChatGPT + Gemini). The report's search-result card names the engine, and
       it must be one of the two that make up the "named X of Y" count on the hero — an AI Overview
       card would cite an engine that is not in that denominator. (This also matches the outreach
       card's brief: "which engine — ChatGPT or Gemini".) */
    for (const engine of SCORED_ENGINES) {
      const er = r.result[engine];
      if (!er || cellNamed(er)) continue;
      const text = (er.answer_text || '').trim();
      if (!text || isJunkAnswer(text)) continue;         // skip map/image/URL junk outright
      /* Stored names are final (see keepRival in buildReportData) — this only drops blanks. */
      const rivals = er.competitors.filter((c) => !!String(c).trim());
      const rival = rivals[0];
      // Gate on extraction: only lead with an answer that is genuinely damning (competitor
      // named / business or category absent / recommendations). The report writes its own
      // clean SUMMARY of this answer — it never uses the extracted snippet verbatim.
      const snippet = extractGutPunch(text, rival);
      if (!snippet) continue;
      /* The card reads like a REAL AI answer (Paul, 2026-09-16): the actual stored answer_text as
         prose, cleaned of markup/UI chrome and trimmed to a sentence boundary — not the short
         damning snippet (that only gates selection above), and never invented. The numbered firms
         render underneath it in the report. */
      const prose = trimToSentence(cleanAnswerText(text), 520);
      let score = 0;
      // (1) Relevance / winnability — dominant.
      if (hasNiche) score += 2_000_000;                  // specialism-relevant, winnable
      else if (isHead) score -= 1_500_000;               // broad vanity head term, unwinnable
      // (2) Damning answer.
      if (looksAbsent(text)) score += 400_000;
      if (rival) score += 200_000;                       // names a real competitor
      // (3) Clarity tiebreak.
      score += Math.min(snippet.length, 400) / 100;
      if (score > bestScore) {
        bestScore = score;
        best = {
          question: r.question,
          engineLabel: ENGINE_LABELS[engine] ?? engine,
          rivals,
          /* The real answer as prose (see `prose` above). Read as an AI answer; firms shown under it. */
          answer: prose,
          /* The real businesses AI named in this one answer, junk-filtered for display. */
          businesses: rivals.filter((c) => isRealCompetitor(c, locationText)).slice(0, 5),
        };
      }
    }
  }
  return best;
}

/* ── MARKET AUDITS ARE NOT CLIENT REPORTS ─────────────────────────────────────────────────────
   A MARKET audit measures a trade in a town with NO business attached: business_name is a
   sentinel ("[market] locksmiths · Hastings") and lead_id is null. It exists to learn who AI names
   in a market, so its named count is 0 by construction — which is correct, and must never be
   rendered as a business's result. A report titled with that sentinel, or a hero verdict reading
   "AI doesn't know you exist" about it, would be indefensible if it ever reached a customer.

   ONE PREDICATE, USED BY EVERY REPORT PATH — the auto-report in process-ai-audit-queue, the public
   render-audit-report renderer, generate-report, the operator's download and the in-app preview.
   It reads the is_market COLUMN, never the name: a string prefix is not a safety guard, and this is
   the guard that stops a public report publishing itself with no human involved. */
export interface MarketAuditFlag { is_market?: boolean | null }

export function isMarketAudit(audit: MarketAuditFlag | null | undefined): boolean {
  return audit?.is_market === true;
}

/** The refusal every report path gives for a market audit. One sentence, so the five call sites
 *  cannot drift into explaining it differently. */
export const MARKET_AUDIT_NO_REPORT =
  'This is a market audit — a trade and a town with no business attached — so it has no client report.';

/** results.seo is only renderable by the report when it's a GRADED object (overall grade +
 *  the three category grades). The queue writes a failure/cap marker ({error, checked_at})
 *  when the SEO step doesn't produce a grade — passing that to the report crashes its
 *  seoSection (reads .categories.onPage). Gate on shape so markers are dropped, not rendered. */
export function isRenderableSeo(s: unknown): s is AiAuditSeo {
  if (!s || typeof s !== 'object') return false;
  const c = (s as { categories?: unknown }).categories as Record<string, unknown> | undefined;
  return !!c && typeof c === 'object' && !!c.onPage && !!c.contentTechnical;
}

const SEO_SEV_RANK: Record<SeoFinding['severity'], number> = { high: 0, med: 1, low: 2 };

/**
 * Fold per-page SEO findings into one line each.
 *
 * WHY. The scan actor reports issues PER CRAWLED PAGE and embeds the count in the message, so
 * a 3-page crawl emits "14 images without alt text" AND "2 images without alt text" carrying
 * the SAME fixHint. collectIssues (seo-scan-core) dedupes by message, which cannot catch these
 * because the messages differ only by their number — so a paying customer saw what reads as
 * the same defect listed twice with different figures. Observed live on a real report.
 *
 * Aggregating at DISPLAY time rather than in the scanner fixes the payloads already stored
 * (every past scan) as well as new ones, with no backfill.
 *
 * Grouping key is the message with its digit runs masked, plus the detail — so the two alt-text
 * lines collapse while genuinely different issues that happen to share a fixHint do not. Counts
 * are summed and written back into the title. A title with no number, or with more than one, is
 * still deduped but never rewritten: there would be no unambiguous figure to sum.
 *
 * That last case is deliberately LOSSY, and worth knowing about. Measured on stored payloads,
 * it collapses pairs like "Thin content: only 266 words" + "only 16 words" (keeping 266) and
 * "Skipped heading level: 2 -> 4" + "1 -> 3" (keeping the first). One line per issue type is the
 * requirement, the fix we sell is the same either way, and the survivor is chosen by highest
 * severity then the actor's own order — but the per-page specifics of the other instances do go.
 * It errs towards understating a problem we are offering to fix, never towards over-claiming.
 */
export function aggregateSeoFindings(findings: SeoFinding[]): SeoFinding[] {
  const groups = new Map<string, { finding: SeoFinding; total: number; numbered: boolean }>();
  for (const f of findings ?? []) {
    const title = (f?.title ?? '').trim();
    if (!title) continue;
    const detail = (f?.detail ?? '').trim();
    const severity = f?.severity ?? 'low';
    const numbers = title.match(/\d+/g) ?? [];
    const numbered = numbers.length === 1;
    const key = `${title.toLowerCase().replace(/\d+/g, '#')}|${detail.toLowerCase()}`;
    const existing = groups.get(key);
    if (!existing) {
      groups.set(key, { finding: { title, detail, severity }, total: numbered ? Number(numbers[0]) : 0, numbered });
      continue;
    }
    // Same issue from another page: add its count and keep the worst severity seen.
    if (existing.numbered && numbered) existing.total += Number(numbers[0]);
    if (SEO_SEV_RANK[severity] < SEO_SEV_RANK[existing.finding.severity]) existing.finding.severity = severity;
  }
  return [...groups.values()].map(({ finding, total, numbered }) =>
    numbered && total > 0
      ? { ...finding, title: finding.title.replace(/\d+/, String(total)) }
      : finding
  );
}

// ── Per-term winnability: fragmentation + cross-engine consensus ─────────────
// Reserves 'locked' for a SMALL, CONSISTENT, own-site incumbent set (few firms named on
// BOTH scored engines, ranking on their own sites, with real citations). Fragmented fields
// (many distinct firms, low cross-engine overlap, directory-driven) read as 'open' — the
// OPPOSITE of the old union-count rule, where more rivals wrongly meant more locked. Shared
// by the badge (AiAudit.tsx) and the report (buildReportData) so the two can't drift.
// isAggregatorUrl is dependency-injected: the SPA and edge keep separate copies of the
// domain lists (the '@/' alias can't resolve in a Deno bundle), so the caller passes its own.
export type Winnability = 'open' | 'contested' | 'locked' | 'named' | 'no-local-race';

export interface WinnabilityResult {
  verdict: Winnability;
  score: number | null;   // /10; null for no-local-race
  U: number;              // distinct real firms across scored engines (normalized)
  C: number;              // firms named on BOTH scored engines (normalized intersection)
  overlap: number;        // C / U (0 when U === 0)
  agg: number;            // aggregator/directory share of non-own citations
  cites: number;          // count of non-own citations across scored engines
  clientNamed: boolean;
  namedFirms: string[];   // display names, deduped, isRealCompetitor-filtered
  reason: string;
}

// Corporate suffixes + generic trade words stripped when matching firm names, so
// "Smith Plumbing" and "J Smith Plumbing Ltd" collapse to the same key ("smith"). Accepted
// trade-off: two different firms sharing a surname can merge (rare, usually one family firm).
// Falls back to the full normalized string if every token strips out.
// Corporate suffixes + connectives ("and"/"of", matching the & → space strip below).
const FIRM_SUFFIXES = new Set(['ltd', 'limited', 'llp', 'plc', 'co', 'inc', 'llc', 'group', 'uk', 'the', 'and', 'of']);
const FIRM_TRADE_GENERIC = new Set([
  'plumbing', 'plumber', 'plumbers', 'heating', 'gas', 'electrical', 'electrician', 'electricians',
  'services', 'service', 'solutions', 'company', 'contractors', 'contractor',
]);

function firmKey(name: string): string {
  const toks = name.toLowerCase().replace(/&/g, ' ').replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/).filter(Boolean)
    .filter((t) => t.length > 1)                                     // drop single-letter initials ("J")
    .filter((t) => !FIRM_SUFFIXES.has(t) && !FIRM_TRADE_GENERIC.has(t));
  return toks.sort().join(' ') || name.trim().toLowerCase();
}

/** Domain of a URL, lowercased + www-stripped; '' on parse failure. */
export function domainOfSafe(url: string): string {
  try { return new URL(/^https?:\/\//i.test(url) ? url : `https://${url}`).hostname.replace(/^www\./, '').toLowerCase(); }
  catch { return ''; }
}

/**
 * Classify ONE question's winnability from its per-engine data. See the block comment above
 * for the rule. `isAggregatorUrl` is injected so this stays runnable in both the SPA and Deno.
 */
export function classifyWinnability(
  result: EngineMap,
  opts: { businessName: string; locationText: string; ownWebsite?: string; isAggregatorUrl: (url: string) => boolean },
): WinnabilityResult {
  const { locationText, ownWebsite = '', isAggregatorUrl } = opts;
  const ownDomain = ownWebsite ? domainOfSafe(ownWebsite) : '';

  let clientNamed = false;
  let scoredNamed = 0;
  let bestPosition: number | null = null;
  // Client named-signal across ALL display engines (defend if named anywhere).
  for (const engine of DISPLAY_ENGINES) {
    const er = result[engine];
    if (!er) continue;
    if (cellNamed(er)) {
      clientNamed = true;
      if ((SCORED_ENGINES as readonly string[]).includes(engine)) scoredNamed++;
      if (er.position != null) bestPosition = bestPosition == null ? er.position : Math.min(bestPosition, er.position);
    }
  }

  // Competitors + citations from the SCORED engines only (chatgpt, gemini) — the engines with
  // real AI-named firm lists and where cross-engine agreement is meaningful.
  const perEngineKeys: Set<string>[] = [];    // firmKey sets, one per scored engine that RAN
  const display = new Map<string, string>();  // firmKey → display name (first seen)
  let citTotal = 0;
  let citAggregator = 0;
  for (const engine of SCORED_ENGINES) {
    const er = result[engine];
    if (!er) continue;                          // engine didn't run for this term
    const keys = new Set<string>();
    for (const c of er.competitors) {
      if (!isRealCompetitor(c, locationText)) continue;
      const k = firmKey(c);
      if (!k) continue;
      keys.add(k);
      if (!display.has(k)) display.set(k, c.trim());
    }
    perEngineKeys.push(keys);
    for (const cit of er.citations) {
      const url = cit?.url;
      if (!url) continue;
      if (ownDomain && domainOfSafe(url).endsWith(ownDomain)) continue;   // own-site citation — skip
      citTotal++;
      if (isAggregatorUrl(url)) citAggregator++;
    }
  }

  const enginesRan = perEngineKeys.length;
  const union = new Set<string>();
  for (const s of perEngineKeys) for (const k of s) union.add(k);
  const U = union.size;
  // Cross-engine consensus: firms named on BOTH scored engines. Only defined when both ran.
  const C = enginesRan >= 2 ? [...perEngineKeys[0]].filter((k) => perEngineKeys[1].has(k)).length : 0;
  const overlap = U > 0 ? C / U : 0;
  const agg = citTotal > 0 ? citAggregator / citTotal : 0;
  const cites = citTotal;
  const namedFirms = [...display.values()];
  const top = namedFirms.slice(0, 3);
  const firmList = top.join(', ') + (U - top.length > 0 ? ` +${U - top.length}` : '');

  // 1) Named anywhere → defend.
  if (clientNamed) {
    let score = 8;
    if (scoredNamed >= 2) score += 1;
    if (bestPosition != null && bestPosition <= 3) score += 1;
    score = Math.min(10, score);
    const namedOn = DISPLAY_ENGINES.filter((e) => cellNamed(result[e])).map((e) => ENGINE_LABELS[e] ?? e);
    return { verdict: 'named', score, U, C, overlap, agg, cites, clientNamed: true, namedFirms,
      reason: `You're already named on ${namedOn.join(', ')} — defend this.` };
  }

  // 2) No real firms named anywhere → generic advice, not a local race.
  if (U === 0) {
    return { verdict: 'no-local-race', score: null, U, C, overlap, agg, cites, clientNamed: false, namedFirms: [],
      reason: 'No local firms named — AI gives generic advice, so there is no local race to win here.' };
  }

  // 3) Locked — a small, cross-engine-consistent set of own-site incumbents. Requires BOTH
  //    engines ran (overlap signal) AND cites >= 2, so a thin/no-citation term can never lock.
  if (enginesRan >= 2 && U <= 3 && C >= 2 && overlap >= 0.5 && agg < 0.4 && cites >= 2) {
    const score = overlap >= 0.75 && agg < 0.2 ? 2 : 3;
    return { verdict: 'locked', score, U, C, overlap, agg, cites, clientNamed: false, namedFirms,
      reason: `A small, consistent set of firms (${firmList}) rank across ChatGPT and Gemini on their own sites — well dug in.` };
  }

  // 4) Open — fragmented (many firms), directory-driven, or no cross-engine consensus.
  if (U >= 6 || agg >= 0.6 || (C === 0 && U >= 2)) {
    const score = (U >= 8 || agg >= 0.6) ? 9 : U >= 6 ? 8 : 7;
    const why = U >= 6 ? `AI names ${U} different firms with little overlap`
      : agg >= 0.6 ? 'incumbents rank off directory listings, not their own sites'
      : 'ChatGPT and Gemini name different firms — no agreed incumbent';
    return { verdict: 'open', score, U, C, overlap, agg, cites, clientNamed: false, namedFirms,
      reason: `${why} (${firmList}); you're absent. A fragmented, winnable field — worth targeting.` };
  }

  // 5) Contested — a middling field.
  const score = agg >= 0.4 ? 6 : agg < 0.2 ? 4 : 5;
  return { verdict: 'contested', score, U, C, overlap, agg, cites, clientNamed: false, namedFirms,
    reason: `AI names ${U} firm${U === 1 ? '' : 's'} (${firmList}); you're absent. A contested field — winnable with focus.` };
}

/** Derive the client report's data from a run's queue rows. Pure — used both for the live
 *  report on the results screen and to build a snapshot when opening a past audit's report.
 *  Returns null until at least one question has completed. */
/* Unwrap a Google redirect citation ("/url?…&url=<real>" or ".../url?…&q=<real>") to the real
   target, so the client sees "privatedoc.com" not "google.com". Non-redirect URLs pass through. */
export function unwrapCitationUrl(raw: string): string {
  const u = (raw ?? '').trim();
  if (!u) return '';
  if (/\/url\?/.test(u)) {
    const m = u.match(/[?&](?:url|q)=([^&]+)/);
    if (m) { try { return decodeURIComponent(m[1]); } catch { return m[1]; } }
  }
  return u;
}

/** Bare hostname of a URL, lowercased, www stripped. '' when it can't be parsed. */
export function citationDomain(raw: string): string {
  const u = unwrapCitationUrl(raw);
  if (!u) return '';
  try {
    const withProto = /^https?:\/\//i.test(u) ? u : `https://${u}`;
    return new URL(withProto).hostname.toLowerCase().replace(/^www\./, '');
  } catch { return ''; }
}

/* ⛔ IS THIS CITATION THE CLIENT'S OWN? Two independent tests, either sufficient:
   the source TITLE names the business, or the source URL is on the business's own domain.
   The title half is what the stored `named` flag already uses (ai-search.ts matches the title, NOT
   the domain — a page titled "Home | Accountants" on the client's own site does not trip it). The
   domain half is what an operator actually means by "we were cited", so both are needed and
   neither alone is enough.
   ⚠️ ownDomain may be '' — the SPA preview did not pass ownWebsite until this change, and an audit
   may genuinely have no website. An empty domain simply disables the domain half; it never matches
   everything, which an unguarded `endsWith('')` would (the absent-value rule). */
export function citationIsClient(
  c: { title?: string; url?: string } | null | undefined,
  businessName: string,
  ownDomain: string,
): boolean {
  if (!c) return false;
  if (nameMatches(c.title ?? '', businessName)) return true;
  if (!ownDomain) return false;
  const host = citationDomain(unwrapCitationUrl(c.url ?? ''));
  return !!host && (host === ownDomain || host.endsWith(`.${ownDomain}`));
}

export type WinnabilityLabel = 'named' | 'wide_open' | 'locked' | 'informational' | 'unclear';

/* ⛔ THE CLIENT'S OWN RESULT OUTRANKS EVERY COMPETITOR SIGNAL. Named in at least this share of the
   scored answers → the question is WON, and the verdict says so instead of grading the race.
   0.5 is the project's existing "already named" bar (DEFEND_NAMED_RATE in pagePlanQueue.ts, the
   Gemini-first hold rule), reused here so the report and the page plan cannot disagree about which
   questions are already won. */
export const WINNABILITY_NAMED_SHARE = 0.5;
export interface QuestionWinnability {
  label: WinnabilityLabel;
  reason: string;
  distinctFirms: number;     // distinct real firms named across all (engine × run) cells
  topFirmCells: number;      // how many cells the most-named firm appeared in
  totalCells: number;        // (engine × run) cells that returned an answer
  sourceMix: { authority: number; business: number; other: number; total: number };
}

/* WINNABILITY for ONE question, computed ACROSS THE REPEATS (engine × run cells). Reliable only
   because Full Measurement now repeats (single-ask winnability is noise — measured 17.9% flip). It
   is INTERNAL: rendered only when the report is asked for internally, never on the client document.
   Conservative — defaults to 'unclear' rather than over-claiming 'wide_open'. `cells` is the list of
   real-firm-name arrays (one per answered engine×run cell, canonical labels); `domains` is every
   cited domain across the question. */
export function computeWinnability(
  cells: string[][],
  domains: string[],
  /* The client's OWN result on this question: how many scored answers named them, out of how many
     scored answers there were. Optional so older callers keep the previous behaviour exactly.
     ⚠️ ABSENT MEANS "NOT MEASURED", NEVER "NOT NAMED" — a missing argument must not be read as a
     zero and turn a won question into "worth testing" (the absent-value rule, CLAUDE.md §6). */
  client?: { named: number; answers: number },
): QuestionWinnability {
  const totalCells = cells.length;
  const tally = new Map<string, number>();
  let firmMentions = 0;
  for (const cell of cells) {
    for (const f of new Set(cell.map((x) => x.toLowerCase()))) { tally.set(f, (tally.get(f) ?? 0) + 1); firmMentions++; }
  }
  /* ⛔ COUNT ONLY FIRMS THAT RECUR ACROSS ≥2 CELLS. A real firm is named across the repeats (engine ×
     run); a one-off prose fragment the extractor scraped ("Brain", "Is AndroFeme", "So I'd") appears
     in a single verbose answer and nowhere else. Requiring ≥2 cells excludes those from the winnability
     count so a dirty run can't inflate distinctFirms and wrongly push a question to WIDE OPEN. This
     leans on the repeats — the exact reason winnability is only computed on a multi-run measurement.
     (extract-competitors cleans the STORED names separately; this is the deterministic backstop.) */
  const distinctFirms = [...tally.values()].filter((c) => c >= 2).length;
  const topFirmCells = tally.size ? Math.max(...tally.values()) : 0;
  const topShare = totalCells > 0 ? topFirmCells / totalCells : 0;
  const mix = sourceMix(domains);
  const authorityLean = mix.total > 0 && mix.authority >= Math.max(1, mix.business);
  let label: WinnabilityLabel;
  let reason: string;
  /* ⛔ TESTED FIRST, BEFORE ANY COMPETITOR GRADING. This function used to see only the rivals and
     the sources, so a question where the client was named in 5 of 6 answers fell through to the
     final `else` and printed "Mixed signals — worth a closer look as a possible content target".
     The document was grading the race while ignoring the fact that the client had already won it,
     which reads as the tool disregarding its own measurement. A won question is not a target. */
  const clientAnswers = client?.answers ?? 0;
  const clientShare = clientAnswers > 0 ? (client!.named / clientAnswers) : 0;
  if (clientAnswers > 0 && clientShare >= WINNABILITY_NAMED_SHARE) {
    label = 'named';
    /* ⚠️ PLAIN TEXT, NOT AN HTML ENTITY. The renderer prints this through esc(), so "&rsquo;" would
       be escaped to "&amp;rsquo;" and show as literal markup on the page. Every other reason string
       here uses literal characters (the em dashes below) for the same reason. */
    reason = `You’re already being named here — in ${client!.named} of ${clientAnswers} answers. Protect this: keep the page that earns it live and current.`;
  }
  else if (totalCells === 0) { label = 'unclear'; reason = 'no answers to read'; }
  else if (firmMentions === 0) {
    if (authorityLean) { label = 'informational'; reason = 'AI answers this with general information rather than naming businesses. Potentially winnable with a strong Q&A or article page — worth testing.'; }
    else { label = 'unclear'; reason = 'no businesses named, but the sources are not clearly informational'; }
  } else if (distinctFirms <= 3 && topShare >= 0.5) {
    label = 'locked'; reason = `dominated — ${distinctFirms} firm${distinctFirms === 1 ? '' : 's'} recur, the top one named in ${topFirmCells} of ${totalCells} answers`;
  } else if (distinctFirms >= 4 && topShare < 0.4 && mix.business >= 1) {
    label = 'wide_open'; reason = `${distinctFirms} different firms named, none dominant, and business-type sources appear — a page could win a place`;
  } else {
    label = 'unclear'; reason = 'Mixed signals — no clear incumbent. Worth a closer look as a possible content target.';
  }
  return { label, reason, distinctFirms, topFirmCells, totalCells, sourceMix: mix };
}

/**
 * Which website presentation an audit gets, from the ONE fact that decides it.
 *
 * ⛔ THE PAID BASELINE IS THE ONLY GRADED REPORT. `baseline_target_runs > 1` is what marks a paid
 * baseline (audit-baseline writes it; a hook audit, a wizard one-off and a bulk audit all leave it
 * null). Everything else is pre-payment, and a letter grade shown to someone who has not bought yet
 * reassures them about the wrong thing — see AiAuditReportData.seoStyle.
 *
 * ⛔ ONE RULE, EVERY CALLER. Six call sites decide this; restating the comparison at each is how the
 * public link and the in-app preview end up disagreeing about what the client is looking at.
 * ⚠️ ABSENT / UNREADABLE → 'issues', NOT 'graded'. A row whose marker we cannot read is far more
 * likely to be an ordinary audit than a paid baseline (2 baselines against ~460 audits), and the
 * safe direction is to withhold a grade rather than to show one we cannot justify.
 */
export function seoStyleForAudit(
  baselineTargetRuns: unknown,
  isMeasurement?: unknown,
): 'graded' | 'issues' {
  const n = typeof baselineTargetRuns === 'number' ? baselineTargetRuns : Number(baselineTargetRuns);
  const multiRun = Number.isFinite(n) && n > 1;
  /* 🔴 `baseline_target_runs > 1` STOPPED MEANING "PAID BASELINE" ON 2026-09-02, and this predicate
     had to learn the difference. The free-check lane now runs 5 questions x 3 runs for accuracy, so
     it writes the same column a paid baseline does — and every one of these call sites would have
     started showing a stranger the graded website block that was deliberately split off the
     pre-payment lanes. The run count is a measurement decision; the grade is a commercial one, and
     they are no longer the same fact.

     The distinction that DOES hold is the one audit-baseline.ts:457 already relies on to protect a
     paying client's day-0: a paid baseline is multi-run AND NOT marked `is_measurement`. Reusing it
     here keeps one meaning for one column rather than adding a second, lane-specific test.
     ⚠️ ABSENT is_measurement -> treated as a baseline, i.e. graded. That is the SAFER direction of
     the two: a free check whose marker we cannot read shows a graded panel with no scan behind it,
     which renders as the "check comes when we start work" line anyway, whereas the other default
     would withhold grades from a paying client's real baseline. */
  return multiRun && isMeasurement !== true ? 'graded' : 'issues';
}

export function buildReportData(
  queueRows: QueueRow[],
  run: RunRow | null,
  ctx: {
    businessName: string; businessType: string; locationText: string; specialisms: string;
    // Injected so the shared winnability rule runs in both the SPA and Deno (see classifyWinnability).
    isAggregatorUrl: (url: string) => boolean;
    ownWebsite?: string;
    /* ⛔ HOW THE WEBSITE SLOT IS PRESENTED — see AiAuditReportData.seoStyle. Passed straight
       through, never derived here: this module has the RUN and the queue rows, not the audit row
       that says whether this is a paid baseline. The CALLER knows; deriving it from run count
       would guess (a 3-run measurement is not the same fact as baseline_target_runs > 1).
       ⚠️ Absent → 'graded', the pre-existing output. */
    seoStyle?: 'graded' | 'issues';
    /** Does the business have a website? true / false only when the caller KNOWS (a site on file, or
     *  Google was consulted and returned none); null = unknown, and the report then says nothing
     *  about their website. Omit to derive true from `ownWebsite` and null otherwise. */
    hasWebsite?: boolean | null;
    /** The audit's created_at: decides its scoring method (aiOverview.ts scoringMethodFor). Absent = method 1. */
    auditCreatedAt?: string | null;
  },
): AiAuditReportData | null {
  /* ⛔ A RUN WE CANNOT PROVE WAS CLEANED PRINTS NO RIVAL NAMES AT ALL. Paul's rule, 2026-08-28:
     "I never want a junk-named report going to a client without me knowing." The deterministic
     filters below catch function words and code-like tokens, but they CANNOT catch content-word
     junk — Solene's report led with "Testosterone" and "Hormone Replacement Therapy" as rival
     firms, and no structural test can know those aren't clinics. So when the stored names carry
     PROOF the LLM cleaner never covered this run, the honest output is silence: the report already
     handles zero rivals gracefully (`hasRivals` gates every clause that mentions competitors), so
     it degrades to "we measured what AI said about you" instead of naming nonsense.
     ⚠️ The verdict is DERIVED from the names, not read from a stamp — every audit before
     2026-08-28 has no stamp, and absence must not read as clean (competitorCleaning.ts). */
  /* ownDomain is the client's own host, used only by the per-engine `cited` derivation below.
     namedCtx lets cellNamed() read the ANSWER TEXT as the ruler (namedSignal.ts) — the same context
     the internal baseline view passes, so hero, per-question and per-engine counts agree with it. */
  const ownDomain = citationDomain(unwrapCitationUrl(ctx.ownWebsite ?? ''));
  const namedCtx = { businessName: ctx.businessName, trade: ctx.businessType || null, town: ctx.locationText || null };
  const cleanliness = assessCompetitorCleanliness(collectCompetitorNames(queueRows), run?.results,
    { answeredCells: countAnsweredCells(queueRows) });
  /* ⚠️ `suppressNames`, NOT `verdict === 'dirty'`. The verdict is also dirty when the run holds NO
     names and no cleaning receipt — nothing to withhold there, and blanking on it would strip the
     gut-punch from historic reports whose regex list happened to be empty. */
  const rivalsSuppressed = cleanliness.suppressNames;
/* 🔴 NO PER-NAME FILTERING AT RENDER ANY MORE — the names were cleaned when the audit ran
     (extract-competitors' cleanNames), and what is stored is what the client reads.
     It used to be `!rivalsSuppressed && isRealCompetitor(c, ctx.locationText)`, and that second half
     rejected 151 of the 2,065 stored names (7%) across the 60 newest audits. Every sampled rejection
     was a real firm: isRealCompetitor drops a short name containing the town, which is exactly how a
     local trade is named — "Keytek Ashby-de-la-Zouch", "LockFit Bournemouth", "Locksmith
     Christchurch". On Hazlewood Locksmiths it hid 6 of 19 real rivals and emptied three engine
     blocks that sat beside a positive named count.
     What it was guarding against had already been handled upstream: of those 2,065 stored names,
     0 were known directories, 0 contained the client's own name, 1 was provable junk.

     ⛔ SUPPRESSION STAYS, AND IT IS A DIFFERENT MECHANISM. It is run-level and fires only when the
     stored list is provably junk (competitorCleaning.ts) — that is "we hold names we cannot trust",
     not "this name looks wrong". Removing it would put the pre-cleaner regex output back on historic
     reports.
     ⚠️ DO NOT REINTRODUCE A PER-NAME TEST HERE. If a bad name ever reaches a report, it got stored,
     so it is cleanNames that needs the rule — one place, at audit time, or the two disagree again. */
  const keepRival = (c: string) => !rivalsSuppressed && !!c.trim();

  let done = 0;
  let liveNamed = 0;
  let liveTotal = 0;
  for (const r of queueRows) {
    if (r.status === 'done' && r.result) {
      done++;
      /* ⛔ COUNT THE ANSWERS THAT EXIST, NOT THE ONES WE ASKED FOR. liveTotal++ used to be
         unconditional: it assumed both scored engines answered every question, so a single engine
         timing out would put a denominator on the report that was one higher than the truth —
         "out of 6 answers" when 5 came back — on the artefact that sells, with nothing to flag it.
         Measured 2026-08-08 across all 835 completed questions: 1,670 claimed, 1,670 real, so no
         report ever sent carried a wrong figure. This makes it true by construction rather than
         true by luck.
         ⚠️ Twenty lines below, perEngine already counted correctly (`if (r.result?.[engine])`).
         Two counting rules in one file was the actual fault. */
      for (const e of SCORED_ENGINES) {
        if (!r.result[e]) continue;
        liveTotal++;
        if (cellNamed(r.result[e], namedCtx)) liveNamed++;
      }
    }
  }
  if (done === 0) return null;

  /* The two numbers behind the total, so the report can show its working. enginesUsed counts the
     SCORED engines that actually returned something on at least one question — not the ones asked
     for, for the same reason the total is now conditional. */
  const enginesSeen = new Set<string>();
  for (const r of queueRows) {
    if (r.status === "done" && r.result) for (const e of SCORED_ENGINES) if (r.result[e]) enginesSeen.add(e);
  }

  /* ⛔ COUNT LIVE ACROSS ALL RUNS, NOT ONE RUN'S STORED SUMMARY. A Full Measurement now asks each
     question over MEASUREMENT_RUNS runs, and the caller passes the queue rows from ALL runs, so
     "named X of Y" is distinct-questions × scored-engines × runs — a frequency, not a single ask.
     run.results.summary is a SINGLE run's tally and would undercount a multi-run audit, so it is no
     longer used. For a single-run audit liveNamed/liveTotal equal that summary anyway (measured:
     1,670 claimed = 1,670 real), so this changes nothing for old audits. */
  /* ⛔ GOOGLE AI IN THE SCORE, BY THE AUDIT'S OWN METHOD (Paul, 2026-10-19; aiOverview.ts scoringMethodFor). An audit
     created on or after GOOGLE_AI_SCORED_SINCE counts Google AI on every answer where Google showed one (none shown =
     left out, never a penalty) — the SAME rule the guarantee comparison applies (measurementCompare scoringMethod), so a
     new client's baseline figure IS the guarantee's before side. Older audits: exactly as before. */
  const googleAiTally = scoringMethodFor(ctx.auditCreatedAt ?? null) === 2 ? overviewTallyFromRows(queueRows, namedCtx) : null;
  const named = liveNamed + (googleAiTally?.named ?? 0);
  const total = liveTotal + (googleAiTally?.shown ?? 0);
  // Distinct questions asked (each appears once PER RUN in queueRows) — the "N ways of asking" line
  // and the per-question breakdown are keyed on this, never on the row count.
  const distinctQuestions = new Set(
    queueRows.filter((r) => r.status === 'done' && r.result).map((r) => r.question.trim().toLowerCase()),
  ).size;
  const runsCount = Math.max(1, done > 0 && distinctQuestions > 0 ? Math.round(done / distinctQuestions) : 1);

  const perEngine = DISPLAY_ENGINES.map((engine) => {
    let n = 0;
    let t = 0;
    for (const r of queueRows) {
      if (r.status === 'done' && r.result?.[engine]) { t++; if (cellNamed(r.result[engine], namedCtx)) n++; }
    }
    return { engine, named: n, total: t };
  }).filter((pe) => pe.total > 0).map((pe) => ({ label: ENGINE_LABELS[pe.engine] ?? pe.engine, named: pe.named, total: pe.total }));

  const counts = new Map<string, { name: string; count: number }>();
  for (const r of queueRows) {
    if (r.status !== 'done' || !r.result) continue;
    for (const engine of DISPLAY_ENGINES) {
      const er = r.result[engine];
      if (!er) continue;
      if (engine === 'google_organic') continue; // organic result TITLES aren't AI-named firms
      for (const c of er.competitors) {
        if (!keepRival(c)) continue;
        const key = c.trim().toLowerCase();
        if (!key) continue;
        const cur = counts.get(key);
        if (cur) cur.count++; else counts.set(key, { name: c.trim(), count: 1 });
      }
    }
  }
  /* ══ WHO AI ACTUALLY RECOMMENDS MOST ══════════════════════════════════════════════════
     ⛔ GROUPING IS A PRECONDITION, NOT A REFINEMENT. Ranking a SPLIT count names the wrong firms
     with more confidence than not ranking at all. Measured on Wilson's Cambridge market
     2026-08-09: "Chapman’s Valeting & Detailing Specialists" (13, curly apostrophe) and
     "Chapman's …" (8, straight) are one firm with 21 — the real leader, ranking below a split of
     itself. Group first, then rank.

     ⚠️ THE DISPLAY NAME IS THE MOST-MENTIONED SPELLING in the group, not the first or the longest.
     It is the form the engines actually use most, which is the one a reader will recognise. */
  const ctxMatch = buildMatchContext(ctx.businessType ?? '', ctx.locationText ?? '');
  const groups = groupNames([...counts.values()].map((c) => c.name), ctxMatch);
  const byGroup = new Map<string, { name: string; count: number; spellings: string[] }>();
  /* ⛔ REVERTED 2026-08-13: THE LABEL IS THE MOST-MENTIONED SPELLING, FULL STOP.
     For one day this preferred the most-mentioned MULTI-WORD spelling, on the reasoning that a bare
     fragment ("Safe") should never wear a group's count. The reasoning was fine and the effect was
     not: a multi-token label is exactly what an extraction fragment looks like, so
     "Checkatrade\n    \n    If" started BEATING clean "Checkatrade" for the label — and that label
     is not only printed, it becomes audit_reply's {{2}} WhatsApp parameter.
     Measured on 60 recent audits, same rows both ways: the parameter went from 0 rejected by Meta
     to 8 (13%), error #132018 "Param text cannot have new-line/tab characters or more than 4
     consecutive spaces". A report cosmetic broke a live send path, because topCompetitors is read
     by _shared/audit-reply.ts as well as by the report.
     ⚠️ THE LESSON, NOT THE PATCH: check who else consumes a list before changing what it contains.
     The fragment problem is real but belongs upstream in the extractor, not in the label chooser.
     ⚠️ The trades stopwords added at the same time are KEPT — they drop "Safe"/"Locksmith" at the
     counting stage, which is where a fragment should die, and they moved no parameter. */
  for (const grp of groups.values()) {
    let total = 0;
    let best = { name: grp.names[0] ?? '', count: -1 };
    for (const n of grp.names) {
      const c = counts.get(n.trim().toLowerCase());
      const got = c?.count ?? 0;
      total += got;
      if (got > best.count) best = { name: n, count: got };
    }
    if (total > 0) byGroup.set(grp.key, { name: best.name, count: total, spellings: grp.names });
  }
  /* Ranked by grouped count, ties broken by name so the order is stable between renders of the
     same audit — a report that reshuffles its competitors on refresh reads as made up. */
  const ranked = [...byGroup.values()].sort((a, b) => b.count - a.count || a.name.localeCompare(b.name));
  const competitors = ranked.slice(0, 4).map((x) => x.name);
  /* Carried WITH counts so the document can say how often, which is the part that makes it
     credible: "Ultimate Valet Cambridge (5)" is checkable, "Ultimate Valet Cambridge" is a claim. */
  const topCompetitors = ranked.slice(0, 3).map((x) => ({ name: x.name, count: x.count }));
  const competitorMentions = ranked.reduce((n, x) => n + x.count, 0);

  /* Per-term winnability is NOT built into the customer report's data. The verdict is not
     defensible yet (77.6% of 402 stored questions read "winnable", 0% ever read "locked", and
     17.9% of repeated questions flipped verdict with no work done), so nothing that renders to a
     prospect or client carries it. classifyWinnability stays exported for the operator view in
     AiAudit.tsx, which labels it unreliable. */

  /* ══ PER-QUESTION BREAKDOWN — GROUPED ACROSS RUNS ══════════════════════════════════════════
     A Full Measurement asks each question once per run, so a question appears once PER RUN in
     queueRows. Group by question and aggregate across the runs: the client card shows a FREQUENCY
     ("named 4 of 6"), each engine shows "named X of R", the rivals/sources are the union across all
     runs, and an INTERNAL winnability signal is computed over the (engine × run) cells (reliable
     only because of the repeats). Same cleaners as the aggregate above; order preserved (first-seen). */
  const byQuestion = new Map<string, { question: string; rows: QueueRow[] }>();
  for (const r of queueRows) {
    if (r.status !== 'done' || !r.result) continue;
    const key = r.question.trim().toLowerCase();
    if (!byQuestion.has(key)) byQuestion.set(key, { question: r.question, rows: [] });
    byQuestion.get(key)!.rows.push(r);
  }

  const questionBreakdown = [...byQuestion.values()].map(({ question, rows }) => {
    // Client named-frequency across runs × SCORED engines — sums to the "named X of Y" headline.
    let namedCount = 0; let answers = 0;
    for (const r of rows) for (const e of SCORED_ENGINES) {
      const er = r.result![e]; if (!er) continue; answers++; if (cellNamed(er, namedCtx)) namedCount++;
    }
    const namedYou = namedCount > 0;

    // Per display-engine, across runs: how many of the runs it named you in, plus its rivals/sources.
    const perEngine = (['chatgpt', 'gemini', 'ai_overview'] as const).map((engine) => {
      let ranCount = 0; let named = 0; let recommended = 0; let cited = 0; let rawRivals = 0;
      /* Google AI Overview only (2026-10-11): runs where the queue RECORDED that Google showed no
         overview. Old audits carry no stamp, so this stays 0 and they render exactly as before. */
      let notShown = 0; let recorded = 0;
      /* Google AI Overview only (2026-10-19): Google's own answer per run, cleaned for reading (never a
         word written — aiOverview.ts overviewSummaryText / overviewFullText), one copy per distinct text.
         The report quotes it under the overview row; ChatGPT / Gemini rows carry no text here. */
      const overviewAnswers: Array<{ text: string; truncated: boolean; full: string }> = [];
      const seenA = new Set<string>();
      const seenR = new Set<string>(); const engRivals: string[] = [];
      const cm = new Map<string, string>();
      for (const r of rows) {
        if (engine === AI_OVERVIEW_ENGINE) {
          /* Read through the one reader (2026-10-19): the stamp where the queue wrote one, else the
             captured answer / the results page — so an audit from before 11 Oct says what it captured. */
          const reading = overviewReadingOf(r.result);
          if (reading) recorded++;
          if (reading === 'not_shown') notShown++;
          const raw = typeof r.result?.[AI_OVERVIEW_ENGINE]?.answer_text === 'string' ? r.result[AI_OVERVIEW_ENGINE]!.answer_text.trim() : '';
          if (reading === 'shown' && raw) {
            const sum = overviewSummaryText(raw);
            const full = overviewFullText(raw);
            const key = full.toLowerCase();
            if ((sum.text || full) && !seenA.has(key)) { seenA.add(key); overviewAnswers.push({ text: sum.text, truncated: sum.truncated, full }); }
          }
        }
        const er = r.result![engine]; if (!er) continue;
        ranCount++; if (cellNamed(er, namedCtx)) named++;
        /* ⛔ RECOMMENDED vs CITED — DERIVED HERE, NOT STORED, AND `named` IS UNTOUCHED.
           The stored `named` is `prose OR a matching source title` (ai-search.ts), so a reader
           could not tell a real recommendation from a citation of the client's own site. Both
           halves are recoverable from data already on the row — answer_text and citations are
           stored per engine — so they are split at RENDER time: no re-audit, no spend, and every
           historical audit gains the breakdown.
           ⚠️ `named` deliberately still drives the header and the hero. This ADDS a figure; it does
           not redefine the metric. Measured before building: for ABLM, recommended = 22 and
           citation-only = 0, so nothing moves — but that is a fact about this audit, not a
           guarantee, which is exactly why both numbers are now shown. */
        /* 🔴 ONE RULER (2026-09-22). This used to be a raw nameMatches() over answer_text while
           `named` (the summary, the hero, buildBaselineView) read cellNamed() — so the internal
           baseline view printed "Gemini 1/3" over "Named in the answer — 0 of 3" for the same
           three cells (MCLocksmiths, 4 of 20 questions disagreed). Both halves now read the one
           predicate in namedSignal.ts: the model's verdict where the extractor recorded one, the
           stored string match otherwise. `cited` stays its own, separate measure — being cited as
           a source is never "named". */
        if (cellNamed(er, namedCtx)) recommended++;
        if ((er.citations ?? []).some((c) => citationIsClient(c, ctx.businessName, ownDomain))) cited++;
        /* ⛔ COUNT WHAT AI ACTUALLY RETURNED, BEFORE FILTERING. `engRivals` is the KEPT list, and an
           empty kept list has three completely different causes: AI named nobody else, every name it
           did return was filtered out as junk, or names are being withheld because the run is dirty.
           The report printed ONE sentence for all three - "No businesses named." - which on a real
           prospect's document sat directly under "Named in the answer - 1 of 1" (Hazlewood Locksmiths,
           2026-09-02: two of its three occurrences). The renderer cannot tell the cases apart from an
           empty array, so the raw count travels with it. */
        for (const c of er.competitors ?? []) {
          const t = c.trim(); if (!t) continue;
          rawRivals++;
          if (!keepRival(c)) continue;
          const k = t.toLowerCase(); if (seenR.has(k)) continue;
          seenR.add(k); engRivals.push(t);
        }
        for (const c of er.citations ?? []) { const url = unwrapCitationUrl(c?.url ?? ''); const dom = citationDomain(url); if (!dom || cm.has(dom)) continue; cm.set(dom, url); }
      }
      return {
        label: ENGINE_LABELS[engine] ?? engine,
        /* ⛔ `counted` = does this engine feed the question's "named in X of Y answers" total?
           Only SCORED_ENGINES do. The rows render DISPLAY_ENGINES, which is wider — AI Overview is
           shown but never counted — so without this flag an AI Overview row showing a count the
           header ignores would look like an arithmetic error. It is absent from the numbers today
           🔴 AND IT IS NOT HYPOTHETICAL: AI Overview IS being scraped again. Measured on the live
           ABLM report 2026-08-29 — it returned on 14 of 20 questions, so its rows showed counts the
           header excludes and the card appeared not to add up. Several comments in this repo still
           claim it is "no longer scraped"; they are stale. The flag is what makes the card
           reconcile: an engine outside SCORED_ENGINES says so on its own row. */
        counted: (SCORED_ENGINES as readonly string[]).includes(engine),
        ran: ranCount > 0, ranCount, runs: rows.length, named, recommended, cited,
        ...(recorded > 0 ? { overviewRecorded: true, notShown } : {}),
        ...(overviewAnswers.length ? { overviewAnswers } : {}),
        rivals: engRivals,
        /* How many names AI returned for this engine BEFORE filtering - see the loop above. */
        rivalsRaw: rawRivals,
        citations: [...cm.entries()].slice(0, 8).map(([domain, url]) => ({ domain, url })),
      };
    });

    // Folded rivals + citations across all runs/engines, and the per-cell firm lists for winnability.
    const raw: string[] = [];
    const domains: string[] = [];
    const cellsRaw: string[][] = []; // real-firm names per answered (engine × run) cell
    for (const r of rows) for (const engine of DISPLAY_ENGINES) {
      if (engine === 'google_organic') continue; // organic titles aren't AI-named firms
      const er = r.result![engine]; if (!er) continue;
      const cell: string[] = [];
      for (const c of er.competitors ?? []) if (keepRival(c)) { raw.push(c.trim()); cell.push(c.trim()); }
      cellsRaw.push(cell);
      for (const c of er.citations ?? []) { const dom = citationDomain(unwrapCitationUrl(c?.url ?? '')); if (dom) domains.push(dom); }
    }
    // Fold spelling variants to one label per firm.
    const grouped = groupNames(raw, ctxMatch);
    const labelFor = new Map<string, string>();
    for (const g of grouped.values()) { const label = g.names[0] ?? ''; for (const n of g.names) labelFor.set(n.trim().toLowerCase(), label); }
    const canon = (name: string) => (labelFor.get(name.toLowerCase()) || name).trim();
    const seen = new Set<string>(); const rivals: string[] = [];
    for (const c of raw) { const label = canon(c); const k = label.toLowerCase(); if (!k || seen.has(k)) continue; seen.add(k); rivals.push(label); }
    const citeByDomain = new Map<string, string>();
    for (const r of rows) for (const engine of DISPLAY_ENGINES) {
      const er = r.result![engine]; if (!er || !Array.isArray(er.citations)) continue;
      for (const c of er.citations) { const url = unwrapCitationUrl(c?.url ?? ''); const domain = citationDomain(url); if (!domain || citeByDomain.has(domain)) continue; citeByDomain.set(domain, url); }
    }
    const citations = [...citeByDomain.entries()].slice(0, 10).map(([domain, url]) => ({ domain, url }));

    // Winnability over the repeats — cells normalised to canonical firm labels so a spelling variant
    // isn't mistaken for a second firm.
    /* The client's own result is passed in so a question they already win is graded as won rather
       than as a content target. Same two numbers the header badge prints, so the verdict and the
       badge can never tell the reader different stories about the same question. */
    const winnability = computeWinnability(
      cellsRaw.map((cell) => cell.map(canon)), domains, { named: namedCount, answers },
    );

    return { question, namedYou, namedCount, answers, rivals, citations, perEngine, winnability };
  });

  const hookStateOnRun = (run?.results as { hook?: unknown } | null | undefined)?.hook;
  const hookSummary = buildHookReportSummary({
      state: hookStateOnRun,
      rows: queueRows,
      engineOrder: SCORED_ENGINES,
      // Hook surfaces say "Google AI", never "Gemini" (Paul, 2026-09-26); the rest of the report keeps ENGINE_LABELS.
      engineLabel: hookEngineLabel,
      namedInstead: (competitors) => rivalsSuppressed ? [] : competitors.filter((n) => !isProvableJunkName(n)).slice(0, 5),
      /* Version 2 only: the "competitors named instead" count across all six answers goes through the
         SAME run-level gate — a run whose rival names are withheld gets no count (null), never 0. */
      rivalFilter: (competitors) => rivalsSuppressed ? null : competitors.filter((n) => n.trim() && !isProvableJunkName(n)),
      // Version 2 only (six-result hook): the same ruler the hero and per-question counts use.
      namedCtx,
      town: ctx.locationText || null,
      trade: ctx.businessType || null,
      scoringMethod: scoringMethodFor(ctx.auditCreatedAt ?? null),
    });

  return {
    businessName: ctx.businessName || 'This business',
    businessType: ctx.businessType || '',
    named,
    total,
    /* ADAPTIVE HOOK SUMMARY (2026-09-20). Present only for a hook run that has stopped on a gap or
       on its question ceiling (src/lib/hookAudit.ts); null on every baseline, measurement, wizard
       and free-check run, and on a hook that failed at the provider — those render exactly as
       before. Rival names go through the same cleanliness gate as the rest of this report. */
    hook: hookSummary,
    /* ⛔ A SIX-RESULT HOOK WITHOUT SIX VALID RESULTS IS NOT A REPORT (Paul, 2026-09-26). It used to
       fall back to the ordinary rendering, which printed a count over whatever answers existed.
       The renderer now shows a plain "incomplete" notice with no figure. (A run still in flight is
       caught earlier by `measuring`.) */
    hookIncomplete: isHookStateV2(hookStateOnRun) && !hookSummary,
    questionBreakdown,
    questionsAsked: distinctQuestions, // DISTINCT questions (each asked runsCount times), not run-rows
    measurementRuns: runsCount,        // how many times each question was asked (per engine)
    enginesUsed: enginesSeen.size, // scored engines that actually returned something
    pct: total > 0 ? Math.round((named / total) * 100) : 0,
    perEngine,
    /* Google AI Overview across the audit's done questions (2026-10-19) — the chip beside ChatGPT and
       Gemini on the report and Outreach. DISPLAY ONLY: never in pct, named, total or any verdict. */
    overview: overviewTallyFromRows(queueRows, namedCtx),
    /* Google AI is in named / total / pct (scoring method 2). Absent = not (every older audit). */
    googleAiInScore: !!googleAiTally,
    competitors,
    /* The audit-wide leaders. The report names THESE, not whoever happened to appear in the one
       answer gutPunch quotes — that is what put "Get A Splash, Fresh Car, Clean Me" on Wilson's
       report while Ultimate Valet, the top firm in his own data, went unmentioned. */
    topCompetitors,
    competitorMentions,
    /* Suppressed alongside every other rival list — the gut-punch LEADS the report, so an
       uncleaned run must not open with "AI recommended Testosterone instead of you". With no
       gutPunch the report falls back to its measured-verdict opening. */
    /* ⛔ EXPOSED SO THE DOCUMENT CAN SAY WHY A LIST IS EMPTY. Suppression already blanked every
       rival name (keepRival returns false for all of them), but the renderer only saw the empty
       result and asserted "No businesses named" - turning "we hold names we do not trust" into
       "AI named nobody", which is a different claim and not one we had evidence for. */
    /* The town, for copy only. It was never on the payload - the renderer had businessName and
       businessType and nothing else - so the CTA could not say where. Same source the audit itself
       used (ctx.locationText, already resolved by create-ai-audit as
       confirmed_location || derived_town || search_location), so the sentence names the town the
       questions were actually asked about rather than a second guess at it. */
    locationText: ctx.locationText ?? "",
    /* ⛔ DERIVED HERE, NEVER STORED, AND IT GATES THE HERO RATHER THAN ADDING A CAVEAT UNDER IT.
       Paul's rule 2026-09-15: "make sure the refusal replaces the hero, not just a line further
       down" — a true sentence below a false headline is still a false headline.
       ⚠️ It reads the SAME three fields the audit was run against (businessName / businessType /
       locationText), so it cannot disagree with what the questions asked about. */
    /* ⛔ AND SINCE 2026-09-15 THE MODEL CAN ANSWER IT, so the refusal is no longer the end of the
       road. `self_named` is gpt-4o's own reading of each answer — it knows "BS4" in an answer
       about Bristol electricians is a postcode, which is the whole reason the string match could
       not be trusted on these names. Where the extractor has read this run, the count IS
       judgeable and the hero renders. The refusal survives ONLY for a name that is all trade and
       town AND has no model verdict to lean on: extraction never ran, or it failed. Absence is
       still not an answer — it is just no longer the ONLY answer. */
    nameNotJudgeable: !nameIsJudgeable({
      businessName: ctx.businessName, trade: ctx.businessType, town: ctx.locationText,
    }) && !runIsModelRead(queueRows),
    namesWithheld: rivalsSuppressed,
    gutPunch: rivalsSuppressed ? null : pickGutPunch(queueRows, ctx.locationText, ctx.specialisms, ctx.businessType),
    // The date the AUDIT WAS MEASURED, not the date someone happened to open the link.
    // render-audit-report rebuilds this on every request, so new Date() re-dated a three-week-old
    // report to today every time it was viewed — which also makes it useless as the day-0 artefact
    // the guarantee's before/after is supposed to rest on. Falls back to now only when the caller
    // did not select created_at (older call sites), which is the previous behaviour.
    generatedAtLabel: new Date(run?.created_at ?? Date.now()).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' }),
    // Only carry a GRADED seo; drop failure/cap markers so the report never crashes on them.
    // Findings are folded here, at the one point BOTH the report renderer and the onboarding
    // results screen read them, so the two can't drift and stored payloads are fixed too.
    seoStyle: ctx.seoStyle,
    seo: (() => {
      const s = (run?.results as { seo?: unknown } | null)?.seo;
      if (!isRenderableSeo(s)) return undefined;
      return { ...s, leadFindings: aggregateSeoFindings(s.leadFindings ?? []) };
    })(),
    // No own website → the report offers to build one instead of leaving a gap. Derived from the
    // website the caller passes, which is the same value that decides whether a scan runs at all.
    /* ⛔ THREE STATES, NOT TWO (2026-09-13). This was `!!ownWebsite`, so an EMPTY website column read
       as "no website" and the report told AD Locksmithing — who has a site — that we would build them
       one. An empty string is absence, not a fact: a caller that KNOWS (render-audit-report reads the
       lead's website and whether Google was ever consulted) passes true/false; a caller that does not
       pass anything gets true when a site is known and NULL otherwise, and the renderer says nothing
       about their website on null. False is only ever asserted, never inferred from a blank. */
    hasWebsite: ctx.hasWebsite !== undefined
      ? ctx.hasWebsite
      : (ctx.ownWebsite && ctx.ownWebsite.trim() ? true : null),
  };
}
